export const getCreateViewUrl = (organization: string, project: string) => {
  return `/v1/${organization}/${project}/views`;
};

/**
 * Registers a view with an optional description. Needs Administrator.
 */
export const createView = async (
  organization: string,
  project: string,
  viewCreate?: ViewCreate,
  options?: Parameters<typeof storytellerFetch>[1],
): Promise<View> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return storytellerFetch<View>(getCreateViewUrl(organization, project), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(viewCreate),
  });
};

export const getCreateViewMutationKey = () => ["createView"] as const;

export const getCreateViewMutationOptions = <
  TError = ErrorType<ErrorResponse | void>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createView>>,
    TError,
    CreateViewMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof storytellerFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof createView>>,
  TError,
  CreateViewMutationVariables,
  TContext
> => {
  const mutationKey = getCreateViewMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createView>>,
    CreateViewMutationVariables
  > = (props) => {
    const { organization, project, data } = props ?? {};

    return createView(organization, project, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CreateViewMutationResult = NonNullable<
  Awaited<ReturnType<typeof createView>>
>;
export type CreateViewMutationBody = BodyType<ViewCreate> | undefined;
export type CreateViewMutationError = ErrorType<ErrorResponse | void>;
export type CreateViewMutationVariables = {
  organization: string;
  project: string;
  data?: BodyType<ViewCreate>;
};

